# Let me analyze the demo transformation pattern
import json

demoi = [
    [8, 6, 6, 3, 5, 1, 9, 6, 6, 2, 6, 4],
    [7, 7, 5, 8, 5, 7, 6, 4, 0, 4, 7, 2],
    [5, 5, 1, 9, 7, 0, 6, 1, 1, 5, 9, 4],
    [6, 9, 5, 2, 4, 0, 1, 7, 4, 0, 5, 5],
    [1, 6, 6, 4, 1, 6, 5, 5, 5, 1, 4, 8]
]

demoout = [
    [8, 2, 2, 3, 5, 1, 9, 2, 2, 2, 2, 4],
    [7, 7, 5, 8, 5, 7, 2, 4, 0, 4, 7, 2],
    [5, 5, 1, 9, 7, 0, 2, 1, 1, 5, 9, 4],
    [2, 9, 5, 2, 4, 0, 1, 7, 4, 0, 5, 5],
    [1, 2, 2, 4, 1, 2, 5, 5, 5, 1, 4, 8]
]

print("=== Comparing output - is it just 6 -> 2 replacement? ===")
def check_transformation(in_grid, out_grid):
    for r, in_row in enumerate(in_grid):
        out_row = out_grid[r]
        for c, (iv, ov) in enumerate(zip(in_row, out_row)):
            if iv == 6:
                if ov != 2:
                    print(f"Row {r}, Col {c}: 6 -> {ov} (not 2!)")
            # if ov == 2 and iv != 6:
            #     print(f"Row {r}, Col {c}: {iv} -> 2 (extra!)")

check_transformation(demoi, demoout)

print("\n=== Checking if all non-6 values are preserved ===")
for r, in_row in enumerate(demoi):
    out_row = demoout[r]
    for c, (iv, ov) in enumerate(zip(in_row, out_row)):
        if iv != 6 and ov != iv:
            print(f"Row {r}, Col {c}: {iv} -> {ov} (changed!)")
